CUPONS = {"COBRA10": 10, "PIXEL25": 25}


def validar_pedido(itens):
    if not itens:
        raise ValueError("O pedido está vazio.")
    for item in itens:
        if item["quantidade"] <= 0:
            raise ValueError(f"Quantidade inválida: {item['nome']}")
        if item["preco"] < 0:
            raise ValueError(f"Preço inválido: {item['nome']}")


def calcular_subtotal(itens):
    return sum(item["preco"] * item["quantidade"] for item in itens)


def aplicar_desconto(subtotal, cupom):
    if cupom is None:
        return subtotal
    if cupom not in CUPONS:
        raise ValueError(f"Cupom desconhecido: {cupom}")
    return subtotal - subtotal * CUPONS[cupom] / 100


def processar_pedido(itens, cupom=None):
    validar_pedido(itens)
    subtotal = calcular_subtotal(itens)
    total = aplicar_desconto(subtotal, cupom)
    return round(total, 2)


