LARGURA_BARRA = 10
BARRAS = [("Vida", "vida", "vida_max"), ("Mana", "mana", "mana_max"), ("Energia", "energia", "energia_max")]


def desenhar_barra(rotulo, atual, maximo):
    atual = max(0, min(atual, maximo))
    cheios = atual * LARGURA_BARRA // maximo
    barra = "#" * cheios + "-" * (LARGURA_BARRA - cheios)
    return f"{rotulo}: [{barra}] {atual}/{maximo}"


def painel(heroi):
    linhas = [desenhar_barra(rotulo, heroi[chave], heroi[chave_max]) for rotulo, chave, chave_max in BARRAS]
    return "\n".join(linhas)


