def preco_com_desconto(preco: float, porcentagem: float = 0) -> float:
    """Devolve o preço com o desconto aplicado, arredondado em 2 casas.

    A porcentagem vai de 0 a 100: 25 quer dizer 25% de desconto.
    """
    return round(preco * (1 - porcentagem / 100), 2)


def buscar_jogo(catalogo: list[dict], titulo: str) -> dict | None:
    """Devolve o jogo do catálogo com esse título, sem diferenciar maiúsculas.

    Se nenhum jogo tiver esse título, devolve None.
    """
    for jogo in catalogo:
        if jogo["titulo"].lower() == titulo.lower():
            return jogo
    return None


def titulos_do_genero(catalogo: list[dict], genero: str) -> list[str]:
    """Devolve os títulos dos jogos do gênero pedido, em ordem alfabética."""
    return sorted(jogo["titulo"] for jogo in catalogo if jogo["genero"] == genero)


def esta_em_promocao(jogo: dict) -> bool:
    """Diz se o jogo está com algum desconto."""
    return jogo["desconto"] > 0


CATALOGO = [
    {"titulo": "Cavaleiros de Pixel", "genero": "RPG", "preco": 59.9, "desconto": 0},
    {"titulo": "Corrida Estelar", "genero": "Corrida", "preco": 39.9, "desconto": 10},
