def analisar_corrida(tempos):
    """Resume os tempos de volta de um piloto, em segundos.

    Devolve um dicionário com o número da volta mais rápida (contando a
    partir de 1; no empate, vale a primeira), o tempo dessa volta, a média
    arredondada em 2 casas e os números das voltas abaixo da média.
    """
    melhor = 0
    for i in range(1, len(tempos)):
        if tempos[i] < tempos[melhor]:
            melhor = i
    media = sum(tempos) / len(tempos)
    abaixo = []
    for numero, tempo in enumerate(tempos, start=1):
        if tempo < media:
            abaixo.append(numero)
    return {
        "melhor_volta": melhor + 1,
        "melhor_tempo": tempos[melhor],
        "media": round(media, 2),
        "voltas_abaixo_da_media": abaixo,
    }


